#!/bin/bash
# generateChaincodes_spatial.sh — regenerates the 34 location-aware contracts
# with a real radio model: serving-cell selection, SINR, admission control
# and capacity accounting.
#
# Generated by scripts/gen-spatial-contracts.js — do not edit by hand.
#
# Run it from the repository root, exactly like the generateChaincodes_part*
# scripts, then upgrade the affected chaincodes.

set -e

# The generated Go lands beside the part5..10 scripts, in scripts/chaincode —
# that is where deploy_functions.sh looks for it. Anchoring to this script's
# own location rather than the current directory means it no longer matters
# where you run it from; running from the repository root used to put the
# contracts one level up, and deploy then reported "directory not found".
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

ALL_CONTRACTS=(
    "LocationBasedAntennaConfig"
    "LocationBasedAssignment"
    "LocationBasedBandwidth"
    "LocationBasedChannelAllocation"
    "LocationBasedCongestion"
    "LocationBasedConnection"
    "LocationBasedCoverage"
    "LocationBasedDynamicRouting"
    "LocationBasedEnergy"
    "LocationBasedFault"
    "LocationBasedInterference"
    "LocationBasedIoTAuthentication"
    "LocationBasedIoTBandwidth"
    "LocationBasedIoTConnection"
    "LocationBasedIoTFault"
    "LocationBasedIoTRegistration"
    "LocationBasedIoTResource"
    "LocationBasedIoTRevocation"
    "LocationBasedIoTSession"
    "LocationBasedIoTStatus"
    "LocationBasedLatency"
    "LocationBasedNetworkHealth"
    "LocationBasedNetworkLoad"
    "LocationBasedPowerManagement"
    "LocationBasedPriority"
    "LocationBasedQoS"
    "LocationBasedResourceAllocation"
    "LocationBasedRoaming"
    "LocationBasedSessionManagement"
    "LocationBasedSignalQuality"
    "LocationBasedSignalStrength"
    "LocationBasedStatus"
    "LocationBasedTraffic"
    "LocationBasedUserActivity"
)

# With no arguments every location-aware contract is regenerated. Named
# arguments narrow it down, which is what the replacement part1-4 scripts
# use so the README's generateChaincodes_part*.sh loop keeps working and
# stays order-independent.
if [ $# -gt 0 ]; then
    contracts=("$@")
    for want in "${contracts[@]}"; do
        found=0
        for have in "${ALL_CONTRACTS[@]}"; do
            [ "$want" = "$have" ] && found=1 && break
        done
        if [ "$found" = "0" ]; then
            echo "$want is not a location-aware contract — it is generated by generateChaincodes_part5..10.sh" >&2
            exit 1
        fi
    done
else
    contracts=("${ALL_CONTRACTS[@]}")
fi

for contract in "${contracts[@]}"; do
    mkdir -p chaincode/$contract
    case $contract in
        LocationBasedAntennaConfig)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedAntennaConfig struct {
    contractapi.Contract
}

// AntennaConfig records a cell reconfiguration: where the antenna now stands and
// what coverage that produces.
type AntennaConfig struct {
    AntennaID     string `json:"antennaID"`
    Config string `json:"config"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    CoverageM     int64  `json:"coverageRadiusM"`
    EdgeRssiMilli int64  `json:"edgeRssiMilliDbm"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedAntennaConfig) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// SetAntennaConfig moves a cell and records the coverage that results.
//
// This contract acts ON an antenna rather than being served BY one: the
// antenna is relocated to (x,y), the registry is updated so every later
// evaluation sees the new position, and the resulting coverage radius is
// computed from the propagation model.
//
// Note for benchmarking: updating the registry is inherent here, not
// optional as it is in the serving contracts. There are only eight cells,
// so several transactions in one block will touch the same record and all
// but one will be rejected with MVCC_READ_CONFLICT. That is not a defect —
// reconfiguring a cell is genuinely a serialised operation — but it means
// this contract measures contention rather than throughput. Benchmark it at
// a low rate, or read the rejection rate as the result.
func (s *LocationBasedAntennaConfig) SetAntennaConfig(ctx contractapi.TransactionContextInterface, antennaID, config, x, y, seed string) error {
    if antennaID == "" {
        return fmt.Errorf("antennaID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    if px < 0 || py < 0 || px > cfg.GridSizeM || py > cfg.GridSizeM {
        return fmt.Errorf("position (%d,%d) is outside the %d m grid", px, py, cfg.GridSizeM)
    }

    ab, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("antenna %s is not registered — call SeedNetwork first", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }

    a.X, a.Y = px, py
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }

    radius, edge := s.coverageRadius(&a, cfg)
    record := AntennaConfig{
        AntennaID:     antennaID,
        Config: config,
        X:             px,
        Y:             py,
        CoverageM:     radius,
        EdgeRssiMilli: edge,
        Timestamp:     txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaID, recordJSON)
}

// coverageRadius finds the furthest distance at which the cell still clears
// the noise floor by the SINR margin, by bisection over the path-loss curve.
func (s *LocationBasedAntennaConfig) coverageRadius(a *Antenna, cfg *NetworkConfig) (int64, int64) {
    noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
    target := noise + cfg.MinSinrMilliDb
    lo, hi := int64(1), cfg.GridSizeM*2
    for lo < hi {
        mid := (lo + hi + 1) / 2
        pl := PathLossMilliDb(mid, a.FreqMHz, cfg.PathLossExponentMilli)
        if RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, 0) >= target {
            lo = mid
        } else {
            hi = mid - 1
        }
    }
    pl := PathLossMilliDb(lo, a.FreqMHz, cfg.PathLossExponentMilli)
    return lo, RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, 0)
}

func (s *LocationBasedAntennaConfig) QueryAsset(ctx contractapi.TransactionContextInterface, antennaID string) (*AntennaConfig, error) {
    assetJSON, err := ctx.GetStub().GetState(antennaID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", antennaID)
    }
    var asset AntennaConfig
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedAntennaConfig) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*AntennaConfig, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*AntennaConfig
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset AntennaConfig
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage reports whether a position falls inside the cell's radius.
func (s *LocationBasedAntennaConfig) ValidateCoverage(ctx contractapi.TransactionContextInterface, antennaID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, antennaID)
    if err != nil {
        return false, err
    }
    return asset.CoverageM > 0, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedAntennaConfig) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedAntennaConfig) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedAntennaConfig) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedAntennaConfig) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedAntennaConfig) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedAntennaConfig) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedAntennaConfig) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedAntennaConfig) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedAntennaConfig) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedAntennaConfig) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedAntennaConfig))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedAssignment)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedAssignment struct {
    contractapi.Contract
}

// Assignment is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Assignment struct {
    EntityID string `json:"entityID"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedAssignment) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AssignAntenna requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedAssignment) AssignAntenna(ctx contractapi.TransactionContextInterface, entityID, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := Assignment{
        EntityID: entityID,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedAssignment) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Assignment, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Assignment
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedAssignment) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Assignment, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Assignment
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Assignment
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedAssignment) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedAssignment) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedAssignment) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedAssignment) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedAssignment) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedAssignment) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedAssignment) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedAssignment) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedAssignment) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedAssignment) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedAssignment) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedAssignment) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Assignment
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedAssignment))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedBandwidth)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedBandwidth struct {
    contractapi.Contract
}

// Bandwidth is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Bandwidth struct {
    EntityID string `json:"entityID"`
    Bandwidth string `json:"bandwidth"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedBandwidth) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AssignBandwidth requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedBandwidth) AssignBandwidth(ctx contractapi.TransactionContextInterface, entityID, bandwidth, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := Bandwidth{
        EntityID: entityID,
        Bandwidth: bandwidth,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedBandwidth) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Bandwidth, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Bandwidth
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedBandwidth) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Bandwidth, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Bandwidth
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Bandwidth
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedBandwidth) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedBandwidth) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedBandwidth) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedBandwidth) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedBandwidth) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedBandwidth) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedBandwidth) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedBandwidth) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedBandwidth) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedBandwidth) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedBandwidth) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedBandwidth) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Bandwidth
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedBandwidth))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedChannelAllocation)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedChannelAllocation struct {
    contractapi.Contract
}

// ChannelAllocation is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type ChannelAllocation struct {
    EntityID string `json:"entityID"`
    ChannelID string `json:"channelID"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedChannelAllocation) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AllocateChannel requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedChannelAllocation) AllocateChannel(ctx contractapi.TransactionContextInterface, entityID, channelID, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := ChannelAllocation{
        EntityID: entityID,
        ChannelID: channelID,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedChannelAllocation) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*ChannelAllocation, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset ChannelAllocation
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedChannelAllocation) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*ChannelAllocation, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*ChannelAllocation
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset ChannelAllocation
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedChannelAllocation) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedChannelAllocation) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedChannelAllocation) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedChannelAllocation) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedChannelAllocation) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedChannelAllocation) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedChannelAllocation) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedChannelAllocation) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedChannelAllocation) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedChannelAllocation) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedChannelAllocation) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedChannelAllocation) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec ChannelAllocation
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedChannelAllocation))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedCongestion)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedCongestion struct {
    contractapi.Contract
}

// Congestion is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Congestion struct {
    EntityID string `json:"entityID"`
    Congestion string `json:"congestion"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedCongestion) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordCongestion requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedCongestion) RecordCongestion(ctx contractapi.TransactionContextInterface, entityID, congestion, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := Congestion{
        EntityID: entityID,
        Congestion: congestion,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedCongestion) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Congestion, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Congestion
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedCongestion) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Congestion, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Congestion
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Congestion
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedCongestion) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedCongestion) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedCongestion) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedCongestion) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedCongestion) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedCongestion) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedCongestion) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedCongestion) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedCongestion) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedCongestion) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedCongestion) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedCongestion) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Congestion
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedCongestion))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedConnection)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedConnection struct {
    contractapi.Contract
}

// Connection is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Connection struct {
    EntityID string `json:"entityID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedConnection) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ConnectEntity requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedConnection) ConnectEntity(ctx contractapi.TransactionContextInterface, entityID, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := Connection{
        EntityID: entityID,
        Status: "",
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedConnection) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Connection, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Connection
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedConnection) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Connection, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Connection
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Connection
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedConnection) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedConnection) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedConnection) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedConnection) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedConnection) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedConnection) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedConnection) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedConnection) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedConnection) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedConnection) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedConnection) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedConnection) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Connection
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedConnection))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedCoverage)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedCoverage struct {
    contractapi.Contract
}

// CoverageRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type CoverageRecord struct {
    EntityID string `json:"entityID"`
    Coverage string `json:"coverage"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedCoverage) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordCoverage requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedCoverage) RecordCoverage(ctx contractapi.TransactionContextInterface, entityID, coverage, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := CoverageRecord{
        EntityID: entityID,
        Coverage: coverage,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedCoverage) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*CoverageRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset CoverageRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedCoverage) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*CoverageRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*CoverageRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset CoverageRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedCoverage) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedCoverage) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedCoverage) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedCoverage) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedCoverage) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedCoverage) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedCoverage) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedCoverage) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedCoverage) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedCoverage) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedCoverage) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedCoverage) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec CoverageRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedCoverage))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedDynamicRouting)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedDynamicRouting struct {
    contractapi.Contract
}

// DynamicRouting is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type DynamicRouting struct {
    EntityID string `json:"entityID"`
    Route string `json:"route"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedDynamicRouting) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// SetDynamicRoute requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedDynamicRouting) SetDynamicRoute(ctx contractapi.TransactionContextInterface, entityID, route, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := DynamicRouting{
        EntityID: entityID,
        Route: route,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedDynamicRouting) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*DynamicRouting, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset DynamicRouting
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedDynamicRouting) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*DynamicRouting, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*DynamicRouting
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset DynamicRouting
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedDynamicRouting) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedDynamicRouting) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedDynamicRouting) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedDynamicRouting) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedDynamicRouting) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedDynamicRouting) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedDynamicRouting) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedDynamicRouting) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedDynamicRouting) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedDynamicRouting) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedDynamicRouting) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedDynamicRouting) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec DynamicRouting
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedDynamicRouting))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedEnergy)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedEnergy struct {
    contractapi.Contract
}

// EnergyRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type EnergyRecord struct {
    EntityID string `json:"entityID"`
    Energy string `json:"energy"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedEnergy) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordEnergy requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedEnergy) RecordEnergy(ctx contractapi.TransactionContextInterface, entityID, energy, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := EnergyRecord{
        EntityID: entityID,
        Energy: energy,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedEnergy) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset EnergyRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedEnergy) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*EnergyRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*EnergyRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset EnergyRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedEnergy) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedEnergy) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedEnergy) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedEnergy) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedEnergy) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedEnergy) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedEnergy) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedEnergy) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedEnergy) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedEnergy) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedEnergy) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedEnergy) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec EnergyRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedEnergy))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedFault)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedFault struct {
    contractapi.Contract
}

// Fault is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Fault struct {
    EntityID string `json:"entityID"`
    FaultType string `json:"faultType"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedFault) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ReportFault requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedFault) ReportFault(ctx contractapi.TransactionContextInterface, entityID, faultType, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := Fault{
        EntityID: entityID,
        FaultType: faultType,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedFault) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Fault, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Fault
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedFault) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Fault, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Fault
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Fault
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedFault) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedFault) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedFault) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedFault) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedFault) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedFault) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedFault) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedFault) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedFault) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedFault) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedFault) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedFault) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Fault
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedFault))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedInterference)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedInterference struct {
    contractapi.Contract
}

// InterferenceRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type InterferenceRecord struct {
    EntityID string `json:"entityID"`
    InterferenceLevel string `json:"interferenceLevel"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedInterference) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordInterference requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedInterference) RecordInterference(ctx contractapi.TransactionContextInterface, entityID, interferenceLevel, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := InterferenceRecord{
        EntityID: entityID,
        InterferenceLevel: interferenceLevel,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedInterference) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*InterferenceRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset InterferenceRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedInterference) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*InterferenceRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*InterferenceRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset InterferenceRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedInterference) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedInterference) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedInterference) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedInterference) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedInterference) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedInterference) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedInterference) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedInterference) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedInterference) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedInterference) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedInterference) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedInterference) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec InterferenceRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedInterference))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTAuthentication)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTAuthentication struct {
    contractapi.Contract
}

// IoTAuthentication is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTAuthentication struct {
    DeviceID string `json:"deviceID"`
    Token string `json:"token"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTAuthentication) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AuthenticateIoT requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTAuthentication) AuthenticateIoT(ctx contractapi.TransactionContextInterface, deviceID, token, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := IoTAuthentication{
        DeviceID: deviceID,
        Token: token,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTAuthentication) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTAuthentication, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTAuthentication
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTAuthentication) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTAuthentication, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTAuthentication
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTAuthentication
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTAuthentication) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTAuthentication) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTAuthentication) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTAuthentication) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedIoTAuthentication) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTAuthentication) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTAuthentication) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedIoTAuthentication) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedIoTAuthentication) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTAuthentication) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTAuthentication) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTAuthentication) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTAuthentication
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTAuthentication))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTBandwidth)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTBandwidth struct {
    contractapi.Contract
}

// IoTBandwidth is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTBandwidth struct {
    DeviceID string `json:"deviceID"`
    Bandwidth string `json:"bandwidth"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTBandwidth) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AllocateIoTBandwidth requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTBandwidth) AllocateIoTBandwidth(ctx contractapi.TransactionContextInterface, deviceID, bandwidth, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := IoTBandwidth{
        DeviceID: deviceID,
        Bandwidth: bandwidth,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTBandwidth) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTBandwidth, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTBandwidth
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTBandwidth) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTBandwidth, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTBandwidth
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTBandwidth
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTBandwidth) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTBandwidth) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTBandwidth) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTBandwidth) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedIoTBandwidth) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTBandwidth) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTBandwidth) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedIoTBandwidth) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedIoTBandwidth) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTBandwidth) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTBandwidth) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTBandwidth) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTBandwidth
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTBandwidth))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTConnection)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTConnection struct {
    contractapi.Contract
}

// IoTConnection is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTConnection struct {
    DeviceID string `json:"deviceID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTConnection) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ConnectIoT requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTConnection) ConnectIoT(ctx contractapi.TransactionContextInterface, deviceID, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := IoTConnection{
        DeviceID: deviceID,
        Status: "",
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTConnection) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTConnection, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTConnection
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTConnection) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTConnection, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTConnection
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTConnection
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTConnection) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTConnection) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTConnection) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTConnection) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedIoTConnection) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTConnection) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTConnection) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedIoTConnection) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedIoTConnection) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTConnection) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTConnection) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTConnection) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTConnection
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTConnection))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTFault)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTFault struct {
    contractapi.Contract
}

// IoTFault is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTFault struct {
    DeviceID string `json:"deviceID"`
    FaultType string `json:"faultType"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTFault) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ReportIoTFault requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTFault) ReportIoTFault(ctx contractapi.TransactionContextInterface, deviceID, faultType, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := IoTFault{
        DeviceID: deviceID,
        FaultType: faultType,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTFault) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTFault, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTFault
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTFault) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTFault, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTFault
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTFault
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTFault) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTFault) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTFault) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTFault) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedIoTFault) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTFault) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTFault) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedIoTFault) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedIoTFault) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTFault) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTFault) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTFault) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTFault
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTFault))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTRegistration)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTRegistration struct {
    contractapi.Contract
}

// IoTRegistration is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTRegistration struct {
    DeviceID string `json:"deviceID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTRegistration) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RegisterIoT requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTRegistration) RegisterIoT(ctx contractapi.TransactionContextInterface, deviceID, status, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := IoTRegistration{
        DeviceID: deviceID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTRegistration) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTRegistration, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTRegistration
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTRegistration) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTRegistration, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTRegistration
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTRegistration
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTRegistration) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTRegistration) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTRegistration) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTRegistration) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedIoTRegistration) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTRegistration) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTRegistration) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedIoTRegistration) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedIoTRegistration) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTRegistration) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTRegistration) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTRegistration) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTRegistration
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTRegistration))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTResource)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTResource struct {
    contractapi.Contract
}

// IoTResource is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTResource struct {
    DeviceID string `json:"deviceID"`
    ResourceID string `json:"resourceID"`
    Amount string `json:"amount"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTResource) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AllocateIoTResource requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTResource) AllocateIoTResource(ctx contractapi.TransactionContextInterface, deviceID, resourceID, amount, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := IoTResource{
        DeviceID: deviceID,
        ResourceID: resourceID,
        Amount: amount,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTResource) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTResource, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTResource
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTResource) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTResource, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTResource
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTResource
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTResource) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTResource) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTResource) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTResource) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedIoTResource) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTResource) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTResource) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedIoTResource) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedIoTResource) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTResource) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTResource) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTResource) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTResource
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTResource))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTRevocation)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTRevocation struct {
    contractapi.Contract
}

// IoTRevocation is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTRevocation struct {
    DeviceID string `json:"deviceID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTRevocation) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RevokeIoT requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTRevocation) RevokeIoT(ctx contractapi.TransactionContextInterface, deviceID, status, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := IoTRevocation{
        DeviceID: deviceID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTRevocation) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTRevocation, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTRevocation
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTRevocation) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTRevocation, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTRevocation
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTRevocation
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTRevocation) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTRevocation) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTRevocation) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTRevocation) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedIoTRevocation) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTRevocation) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTRevocation) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedIoTRevocation) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedIoTRevocation) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTRevocation) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTRevocation) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTRevocation) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTRevocation
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTRevocation))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTSession)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTSession struct {
    contractapi.Contract
}

// IoTSession is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTSession struct {
    DeviceID string `json:"deviceID"`
    SessionID string `json:"sessionID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTSession) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// StartIoTSession requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTSession) StartIoTSession(ctx contractapi.TransactionContextInterface, deviceID, sessionID, status, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := IoTSession{
        DeviceID: deviceID,
        SessionID: sessionID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTSession) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTSession, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTSession
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTSession) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTSession, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTSession
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTSession
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTSession) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTSession) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTSession) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTSession) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedIoTSession) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTSession) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTSession) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedIoTSession) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedIoTSession) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTSession) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTSession) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTSession) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTSession
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTSession))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTStatus)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTStatus struct {
    contractapi.Contract
}

// IoTStatus is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTStatus struct {
    DeviceID string `json:"deviceID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTStatus) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// UpdateIoTStatus requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTStatus) UpdateIoTStatus(ctx contractapi.TransactionContextInterface, deviceID, status, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := IoTStatus{
        DeviceID: deviceID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTStatus) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTStatus, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTStatus
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTStatus) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTStatus, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTStatus
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTStatus
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTStatus) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTStatus) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTStatus) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTStatus) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedIoTStatus) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTStatus) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTStatus) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedIoTStatus) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedIoTStatus) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTStatus) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTStatus) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTStatus) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTStatus
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTStatus))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedLatency)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedLatency struct {
    contractapi.Contract
}

// Latency is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Latency struct {
    EntityID string `json:"entityID"`
    Latency string `json:"latency"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedLatency) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordLatency requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedLatency) RecordLatency(ctx contractapi.TransactionContextInterface, entityID, latency, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := Latency{
        EntityID: entityID,
        Latency: latency,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedLatency) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Latency, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Latency
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedLatency) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Latency, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Latency
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Latency
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedLatency) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedLatency) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedLatency) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedLatency) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedLatency) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedLatency) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedLatency) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedLatency) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedLatency) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedLatency) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedLatency) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedLatency) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Latency
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedLatency))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedNetworkHealth)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedNetworkHealth struct {
    contractapi.Contract
}

// NetworkHealth is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type NetworkHealth struct {
    EntityID string `json:"entityID"`
    HealthStatus string `json:"healthStatus"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedNetworkHealth) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordNetworkHealth requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedNetworkHealth) RecordNetworkHealth(ctx contractapi.TransactionContextInterface, entityID, healthStatus, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := NetworkHealth{
        EntityID: entityID,
        HealthStatus: healthStatus,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedNetworkHealth) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*NetworkHealth, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset NetworkHealth
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedNetworkHealth) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*NetworkHealth, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*NetworkHealth
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset NetworkHealth
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedNetworkHealth) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedNetworkHealth) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedNetworkHealth) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedNetworkHealth) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedNetworkHealth) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedNetworkHealth) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedNetworkHealth) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedNetworkHealth) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedNetworkHealth) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedNetworkHealth) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedNetworkHealth) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedNetworkHealth) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec NetworkHealth
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedNetworkHealth))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedNetworkLoad)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedNetworkLoad struct {
    contractapi.Contract
}

// NetworkLoadRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type NetworkLoadRecord struct {
    EntityID string `json:"entityID"`
    Load string `json:"load"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedNetworkLoad) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordNetworkLoad requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedNetworkLoad) RecordNetworkLoad(ctx contractapi.TransactionContextInterface, entityID, load, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := NetworkLoadRecord{
        EntityID: entityID,
        Load: load,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedNetworkLoad) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*NetworkLoadRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset NetworkLoadRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedNetworkLoad) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*NetworkLoadRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*NetworkLoadRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset NetworkLoadRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedNetworkLoad) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedNetworkLoad) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedNetworkLoad) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedNetworkLoad) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedNetworkLoad) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedNetworkLoad) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedNetworkLoad) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedNetworkLoad) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedNetworkLoad) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedNetworkLoad) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedNetworkLoad) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedNetworkLoad) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec NetworkLoadRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedNetworkLoad))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedPowerManagement)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedPowerManagement struct {
    contractapi.Contract
}

// PowerManagement is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type PowerManagement struct {
    EntityID string `json:"entityID"`
    PowerLevel string `json:"powerLevel"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedPowerManagement) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// SetPowerLevel requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedPowerManagement) SetPowerLevel(ctx contractapi.TransactionContextInterface, entityID, powerLevel, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := PowerManagement{
        EntityID: entityID,
        PowerLevel: powerLevel,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedPowerManagement) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*PowerManagement, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset PowerManagement
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedPowerManagement) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*PowerManagement, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*PowerManagement
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset PowerManagement
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedPowerManagement) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedPowerManagement) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedPowerManagement) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedPowerManagement) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedPowerManagement) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedPowerManagement) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedPowerManagement) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedPowerManagement) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedPowerManagement) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedPowerManagement) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedPowerManagement) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedPowerManagement) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec PowerManagement
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedPowerManagement))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedPriority)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedPriority struct {
    contractapi.Contract
}

// Priority is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Priority struct {
    EntityID string `json:"entityID"`
    Priority string `json:"priority"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedPriority) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AssignPriority requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedPriority) AssignPriority(ctx contractapi.TransactionContextInterface, entityID, priority, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := Priority{
        EntityID: entityID,
        Priority: priority,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedPriority) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Priority, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Priority
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedPriority) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Priority, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Priority
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Priority
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedPriority) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedPriority) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedPriority) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedPriority) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedPriority) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedPriority) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedPriority) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedPriority) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedPriority) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedPriority) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedPriority) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedPriority) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Priority
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedPriority))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedQoS)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedQoS struct {
    contractapi.Contract
}

// QoS is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type QoS struct {
    EntityID string `json:"entityID"`
    QoSLevel string `json:"qosLevel"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedQoS) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AssignQoS requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedQoS) AssignQoS(ctx contractapi.TransactionContextInterface, entityID, qosLevel, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := QoS{
        EntityID: entityID,
        QoSLevel: qosLevel,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedQoS) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*QoS, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset QoS
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedQoS) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*QoS, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*QoS
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset QoS
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedQoS) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedQoS) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedQoS) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedQoS) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedQoS) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedQoS) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedQoS) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedQoS) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedQoS) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedQoS) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedQoS) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedQoS) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec QoS
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedQoS))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedResourceAllocation)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedResourceAllocation struct {
    contractapi.Contract
}

// ResourceAllocation is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type ResourceAllocation struct {
    EntityID string `json:"entityID"`
    ResourceID string `json:"resourceID"`
    Amount string `json:"amount"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedResourceAllocation) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AllocateResource requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedResourceAllocation) AllocateResource(ctx contractapi.TransactionContextInterface, entityID, resourceID, amount, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := ResourceAllocation{
        EntityID: entityID,
        ResourceID: resourceID,
        Amount: amount,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedResourceAllocation) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*ResourceAllocation, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset ResourceAllocation
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedResourceAllocation) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*ResourceAllocation, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*ResourceAllocation
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset ResourceAllocation
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedResourceAllocation) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedResourceAllocation) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedResourceAllocation) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedResourceAllocation) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedResourceAllocation) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedResourceAllocation) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedResourceAllocation) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedResourceAllocation) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedResourceAllocation) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedResourceAllocation) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedResourceAllocation) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedResourceAllocation) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec ResourceAllocation
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedResourceAllocation))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedRoaming)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedRoaming struct {
    contractapi.Contract
}

// RoamingRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type RoamingRecord struct {
    EntityID string `json:"entityID"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedRoaming) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// PerformRoaming requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedRoaming) PerformRoaming(ctx contractapi.TransactionContextInterface, entityID, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := RoamingRecord{
        EntityID: entityID,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedRoaming) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*RoamingRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset RoamingRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedRoaming) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*RoamingRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*RoamingRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset RoamingRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedRoaming) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedRoaming) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedRoaming) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedRoaming) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedRoaming) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedRoaming) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedRoaming) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedRoaming) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedRoaming) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedRoaming) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedRoaming) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedRoaming) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec RoamingRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedRoaming))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedSessionManagement)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedSessionManagement struct {
    contractapi.Contract
}

// SessionManagement is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type SessionManagement struct {
    EntityID string `json:"entityID"`
    SessionID string `json:"sessionID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedSessionManagement) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ManageSession requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedSessionManagement) ManageSession(ctx contractapi.TransactionContextInterface, entityID, sessionID, status, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := SessionManagement{
        EntityID: entityID,
        SessionID: sessionID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedSessionManagement) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*SessionManagement, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset SessionManagement
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedSessionManagement) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*SessionManagement, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*SessionManagement
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset SessionManagement
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedSessionManagement) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedSessionManagement) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedSessionManagement) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedSessionManagement) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedSessionManagement) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedSessionManagement) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedSessionManagement) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedSessionManagement) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedSessionManagement) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedSessionManagement) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedSessionManagement) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedSessionManagement) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec SessionManagement
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedSessionManagement))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedSignalQuality)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedSignalQuality struct {
    contractapi.Contract
}

// SignalQuality is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type SignalQuality struct {
    EntityID string `json:"entityID"`
    SignalQuality string `json:"signalQuality"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedSignalQuality) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordSignalQuality requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedSignalQuality) RecordSignalQuality(ctx contractapi.TransactionContextInterface, entityID, signalQuality, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := SignalQuality{
        EntityID: entityID,
        SignalQuality: signalQuality,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedSignalQuality) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*SignalQuality, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset SignalQuality
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedSignalQuality) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*SignalQuality, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*SignalQuality
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset SignalQuality
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedSignalQuality) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedSignalQuality) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedSignalQuality) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedSignalQuality) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedSignalQuality) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedSignalQuality) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedSignalQuality) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedSignalQuality) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedSignalQuality) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedSignalQuality) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedSignalQuality) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedSignalQuality) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec SignalQuality
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedSignalQuality))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedSignalStrength)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedSignalStrength struct {
    contractapi.Contract
}

// SignalStrengthRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type SignalStrengthRecord struct {
    EntityID string `json:"entityID"`
    Signal string `json:"signal"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedSignalStrength) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordSignalStrength requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedSignalStrength) RecordSignalStrength(ctx contractapi.TransactionContextInterface, entityID, signal, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := SignalStrengthRecord{
        EntityID: entityID,
        Signal: signal,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedSignalStrength) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*SignalStrengthRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset SignalStrengthRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedSignalStrength) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*SignalStrengthRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*SignalStrengthRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset SignalStrengthRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedSignalStrength) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedSignalStrength) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedSignalStrength) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedSignalStrength) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedSignalStrength) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedSignalStrength) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedSignalStrength) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedSignalStrength) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedSignalStrength) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedSignalStrength) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedSignalStrength) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedSignalStrength) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec SignalStrengthRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedSignalStrength))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedStatus)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedStatus struct {
    contractapi.Contract
}

// Status is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Status struct {
    EntityID string `json:"entityID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedStatus) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// UpdateStatus requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedStatus) UpdateStatus(ctx contractapi.TransactionContextInterface, entityID, status, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := Status{
        EntityID: entityID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedStatus) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Status, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Status
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedStatus) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Status, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Status
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Status
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedStatus) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedStatus) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedStatus) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedStatus) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedStatus) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedStatus) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedStatus) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedStatus) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedStatus) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedStatus) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedStatus) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedStatus) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Status
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedStatus))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedTraffic)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedTraffic struct {
    contractapi.Contract
}

// Traffic is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Traffic struct {
    EntityID string `json:"entityID"`
    Traffic string `json:"traffic"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedTraffic) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordTraffic requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedTraffic) RecordTraffic(ctx contractapi.TransactionContextInterface, entityID, traffic, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := Traffic{
        EntityID: entityID,
        Traffic: traffic,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedTraffic) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Traffic, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Traffic
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedTraffic) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Traffic, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Traffic
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Traffic
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedTraffic) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedTraffic) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedTraffic) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedTraffic) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedTraffic) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedTraffic) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedTraffic) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedTraffic) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedTraffic) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedTraffic) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedTraffic) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedTraffic) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Traffic
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedTraffic))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedUserActivity)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedUserActivity struct {
    contractapi.Contract
}

// UserActivity is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type UserActivity struct {
    UserID string `json:"userID"`
    Activity string `json:"activity"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedUserActivity) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordUserActivity requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedUserActivity) RecordUserActivity(ctx contractapi.TransactionContextInterface, userID, activity, x, y, seed string) error {
    if userID == "" {
        return fmt.Errorf("userID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, userID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when capacity is actually being tracked. See SeedNetwork.
    if trackCapacity {
        best.UsedCapacity++
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    record := UserActivity{
        UserID: userID,
        Activity: activity,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(userID, recordJSON)
}

func (s *LocationBasedUserActivity) QueryAsset(ctx contractapi.TransactionContextInterface, userID string) (*UserActivity, error) {
    assetJSON, err := ctx.GetStub().GetState(userID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", userID)
    }
    var asset UserActivity
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedUserActivity) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*UserActivity, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*UserActivity
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset UserActivity
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedUserActivity) ValidateCoverage(ctx contractapi.TransactionContextInterface, userID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, userID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedUserActivity) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedUserActivity) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedUserActivity) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

func (s *LocationBasedUserActivity) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedUserActivity) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedUserActivity) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate is where the network decision actually happens.
//
// Every antenna is a candidate. Received power is computed for each one
// through path loss and a per-link shadow fade; the strongest becomes the
// serving cell and all the others become interference. SINR follows from
// summing that interference with thermal noise in the linear domain.
func (s *LocationBasedUserActivity) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    var best *Antenna
    bestRssi := int64(-1 << 40)
    rssi := make([]int64, len(antennas))
    bestIdx := 0
    bestDist := int64(0)
    bestPl := int64(0)
    bestShadow := int64(0)

    for i, a := range antennas {
        d := DistanceM(x, y, a.X, a.Y)
        pl := PathLossMilliDb(d, a.FreqMHz, cfg.PathLossExponentMilli)
        sh := ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, sh)
        if rssi[i] > bestRssi {
            bestRssi = rssi[i]
            best = a
            bestIdx = i
            bestDist = d
            bestPl = pl
            bestShadow = sh
        }
    }
    if best == nil {
        return nil, nil, fmt.Errorf("no serving cell could be selected")
    }

    interferers := make([]int64, 0, len(antennas)-1)
    for i := range antennas {
        if i != bestIdx {
            interferers = append(interferers, rssi[i])
        }
    }
    noise := NoiseFloorMilliDbm(best.BandwidthHz, cfg.NoiseFigureMilliDb)
    sinr := SinrMilliDb(bestRssi, interferers, noise)

    return &CellReport{
        ServingCell:   best.AntennaID,
        DistanceM:     bestDist,
        RssiMilliDbm:  bestRssi,
        SinrMilliDb:   sinr,
        CapacityBps:   ShannonBps(best.BandwidthHz, sinr),
        PathLossMilli: bestPl,
        ShadowMilliDb: bestShadow,
        Candidates:    int64(len(antennas)),
        UsedCapacity:  best.UsedCapacity,
        MaxCapacity:   best.MaxCapacity,
    }, best, nil
}

// admit runs the evaluation and applies the two rules that can refuse a
// connection: coverage and capacity. Refusal is the point — before this
// change every transaction succeeded, because nothing was ever checked.
func (s *LocationBasedUserActivity) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    rep, best, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }
    if rep.SinrMilliDb < cfg.MinSinrMilliDb {
        return rep, best, fmt.Errorf(
            "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
            rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
    }
    if cfg.TrackCapacity && best.UsedCapacity >= best.MaxCapacity {
        return rep, best, fmt.Errorf(
            "cell %s is saturated: %d of %d in use",
            best.AntennaID, best.UsedCapacity, best.MaxCapacity)
    }
    return rep, best, nil
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedUserActivity) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    rep, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return rep, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedUserActivity) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedUserActivity) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec UserActivity
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedUserActivity))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        *)
            echo "No template for $contract" >&2
            exit 1
            ;;
    esac

    (
      cd chaincode/$contract
      if [ ! -f go.mod ]; then
          go mod init $contract >/dev/null 2>&1
      fi
      go mod edit -require=github.com/hyperledger/fabric-contract-api-go@v1.2.1
      go mod tidy >/dev/null 2>&1
      go mod vendor >/dev/null 2>&1
    )
done

echo "Regenerated ${#contracts[@]} of ${#ALL_CONTRACTS[@]} location-aware contracts in $SCRIPT_DIR/chaincode"
for contract in "${contracts[@]}"; do
    if [ -f "chaincode/$contract/chaincode.go" ]; then
        echo " - $contract: OK"
    else
        echo " - $contract: Failed"
    fi
done
